from pyspark.sql import functions as F, Window

def run(spark, tables):
    claims = tables['claims']
    
    # Sort the claims DataFrame by IDpol and ClaimAmount
    claims_sorted = claims.orderBy(F.col('IDpol'), F.col('ClaimAmount'))
    
    # Use the FIRST() window function to find the first claim for each policy
    first_claim = claims_sorted.withColumn('first_claim', F.first('ClaimAmount').over(Window.partitionBy('IDpol').orderBy('ClaimAmount')))
    
    # Select only the IDpol and first_claim columns
    result = first_claim.select('IDpol', 'first_claim')
    
    return result
